describe("SPEC-CORE-001: Parse a .feat file to BuiltSpec IR", () => {
  let h: Harness;
  beforeAll(async () => {
    h = await createHarness({ configPath: CONFIG_PATH, specPath: SPEC_PATH, cases: CASES });
  });
  afterAll(async () => {
    await h?.teardown(); // createHarness may have thrown: nothing to tear down
  });
  for (const c of CASES) {
    it(c.name, async () => {
      await h.runCase(c, INLINE);
    });
  }
});
